checks = Counter(); errors = []; numeric_checked = 0; max_metric_error = 0.0; max_timing_error = 0.0

def verify(ok, category, detail):
    checks[category] += 1
    if not ok: errors.append({'category':category,'detail':detail})

def read(p): return json.loads(Path(p).read_bytes())
def digest(p):
    h=sha256()
    with Path(p).open('rb') as f:
        for x in iter(lambda:f.read(8*1024*1024),b''): h.update(x)
    return h.hexdigest()
def fp(x): return sha256(json.dumps(x,sort_keys=True,ensure_ascii=False,allow_nan=False).encode()).hexdigest()
def near(a,b,label,tol=1e-12,category='numeric_metrics'):
    global numeric_checked,max_metric_error,max_timing_error
    numeric_checked += 1
    diff=abs(a-b)
    if category=='numeric_timing': max_timing_error=max(max_timing_error,diff)
    else: max_metric_error=max(max_metric_error,diff)
    verify(math.isfinite(a) and math.isfinite(b) and diff<=tol,category,f'{label}: {a} versus {b}')
def same_tree(a,b,path='comparison'):
    if isinstance(a,dict):
        verify(isinstance(b,dict) and set(a)==set(b),'comparison_structure',path)
        if isinstance(b,dict):
            for k in a.keys() & b.keys(): same_tree(a[k],b[k],path+'.'+k)
    elif isinstance(a,(int,float)) and not isinstance(a,bool): near(float(a),float(b),path)
    else: verify(a==b,'comparison_values',path)
def stats(values):
    values=sorted(values); n=len(values)
    if not values: return None
    def pct(q):
        x=(n-1)*q; a=math.floor(x); b=math.ceil(x)
        return values[a]+(values[b]-values[a])*(x-a)
    return {'count':n,'p50':pct(.5),'p95':pct(.95),'mean':math.fsum(values)/n,'min':values[0],'max':values[-1]}
def inventory(directory): return {str(p.relative_to(directory)):digest(p) for p in sorted(directory.rglob('*')) if p.is_file()}
def metric(rows,positive):
    names=['hit_at_1','recall_at_1','hit_at_5','recall_at_5','hit_at_10','recall_at_10','mrr','average_precision']
    if rows is None: return dict.fromkeys(names,0.)
    hits=[int(r['image_id'] in positive) for r in rows]; out={}
    for k in (1,5,10):
        out[f'hit_at_{k}']=float(any(hits[:k])); out[f'recall_at_{k}']=sum(hits[:k])/len(positive)
    out['mrr']=1/next(k for k,v in enumerate(hits,1) if v)
    out['average_precision']=math.fsum(sum(hits[:k])/k for k,v in enumerate(hits,1) if v)/len(positive)
    return out

