tokenizer=MarianTokenizer.from_pretrained(str(ROOT/'models/opus-mt-zh-en'),local_files_only=True,trust_remote_code=False)
def reqs(text):
    occupied=set(); found={}
    entries=glossary['entries']
    for src,e in sorted([(s,e) for e in entries for s in e['sources']],key=lambda x:-len(x[0])):
        if e.get('required_context','') not in text: continue
        excluded=set()
        for excl in e.get('exclude_within',[]):
            excluded.update(k for m in re.finditer(re.escape(excl),text) for k in range(m.start(),m.end()))
        for m in re.finditer(re.escape(src),text):
            pos=set(range(m.start(),m.end()))
            if not pos.intersection(occupied|excluded): occupied.update(pos); found.setdefault(e['id'],[]).append((m.start(),src))
    return [{'id':e['id'],'source_terms':list(dict.fromkeys(s for _,s in sorted(found[e['id']]))),'target_forms':e['target_forms']+[s[0].upper()+s[1:] for s in e['target_forms']]} for e in entries if e['id'] in found]
